class Vault(
    private val store: Store,          // private: not nameable outside the class
    private val policy: Policy,
) : Readable by store {                // compiler-generated forwarding for Readable
    override fun read(who: Subject, id: String): Record {
        require(policy.allows(who, id)) { "denied: $id" }   // checked before delegation
        return store.read(who, id)
    }
}
